-- QILT structured outcomes foundation. QILT is Layer 2A enrichment only and cannot create/redefine Provider/Course identity.
create table if not exists ref.outcome_surveys (id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,source_family text not null,description text,status text not null default 'active' check(status in ('active','inactive','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ref.outcome_metrics (id uuid primary key default gen_random_uuid(),survey_id uuid not null references ref.outcome_surveys(id) on delete restrict,code text not null,name text not null,category text,unit text not null default 'percent',higher_is_better boolean,description text,status text not null default 'active' check(status in ('active','inactive','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(survey_id,code));
create table if not exists ref.external_study_areas (id uuid primary key default gen_random_uuid(),source_system text not null,external_code text not null,name text not null,description text,status text not null default 'active' check(status in ('active','inactive','retired')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_system,external_code));
create table if not exists ref.external_study_area_mappings (id uuid primary key default gen_random_uuid(),external_study_area_id uuid not null references ref.external_study_areas(id) on delete cascade,field_of_study_id uuid not null references ref.fields_of_study(id) on delete restrict,match_method text not null default 'manual',confidence numeric(5,4),status text not null default 'active' check(status in ('active','inactive','review')),verified_by uuid references auth.users(id) on delete set null,verified_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(external_study_area_id,field_of_study_id));
create table if not exists pipeline.source_provider_mappings (id uuid primary key default gen_random_uuid(),source_id uuid not null references pipeline.sources(id) on delete cascade,source_entity_key text not null,source_entity_name text,provider_id uuid references catalogue.providers(id) on delete restrict,match_method text not null default 'unmatched',match_confidence numeric(5,4),status text not null default 'unmatched' check(status in ('unmatched','candidate','verified','rejected')),verified_by uuid references auth.users(id) on delete set null,verified_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_id,source_entity_key));
create table if not exists catalogue.provider_outcomes (id uuid primary key default gen_random_uuid(),provider_id uuid not null references catalogue.providers(id) on delete cascade,survey_id uuid not null references ref.outcome_surveys(id) on delete restrict,metric_id uuid not null references ref.outcome_metrics(id) on delete restrict,external_study_area_id uuid references ref.external_study_areas(id) on delete restrict,study_level_id uuid references ref.study_levels(id) on delete restrict,audience text not null default 'all' check(audience in ('all','domestic','international','mixed','unknown')),collection_year_from smallint not null,collection_year_to smallint not null,metric_value numeric not null,response_count integer,confidence_low numeric,confidence_high numeric,national_benchmark numeric,source_id uuid not null references pipeline.sources(id) on delete restrict,evidence_id uuid references pipeline.evidence_artifacts(id) on delete restrict,source_institution_key text,source_study_area_code text,source_metric_code text,observed_at timestamptz not null default now(),status text not null default 'current' check(status in ('current','superseded','withdrawn','review')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(collection_year_to>=collection_year_from),check(response_count is null or response_count>=0));
create unique index if not exists uq_provider_outcome_observation on catalogue.provider_outcomes(provider_id,survey_id,metric_id,coalesce(external_study_area_id,'00000000-0000-0000-0000-000000000000'::uuid),coalesce(study_level_id,'00000000-0000-0000-0000-000000000000'::uuid),audience,collection_year_from,collection_year_to,source_id);
create index if not exists idx_provider_outcomes_provider_period on catalogue.provider_outcomes(provider_id,collection_year_to desc); create index if not exists idx_provider_outcomes_metric on catalogue.provider_outcomes(metric_id,audience,collection_year_to desc); create index if not exists idx_provider_outcomes_study_area on catalogue.provider_outcomes(external_study_area_id,study_level_id); create index if not exists idx_source_provider_mappings_provider on pipeline.source_provider_mappings(provider_id) where provider_id is not null; create index if not exists idx_external_study_area_mapping_field on ref.external_study_area_mappings(field_of_study_id);
alter table ref.outcome_surveys enable row level security; alter table ref.outcome_metrics enable row level security; alter table ref.external_study_areas enable row level security; alter table ref.external_study_area_mappings enable row level security; alter table pipeline.source_provider_mappings enable row level security; alter table catalogue.provider_outcomes enable row level security;
revoke all on ref.outcome_surveys,ref.outcome_metrics,ref.external_study_areas,ref.external_study_area_mappings from anon,authenticated; revoke all on pipeline.source_provider_mappings,catalogue.provider_outcomes from anon,authenticated; grant all on ref.outcome_surveys,ref.outcome_metrics,ref.external_study_areas,ref.external_study_area_mappings,pipeline.source_provider_mappings,catalogue.provider_outcomes to service_role;
insert into ref.outcome_surveys(code,name,source_family,description) values ('qilt_ses','Student Experience Survey','QILT','Student experience measures published through QILT/ComparED.'),('qilt_gos','Graduate Outcomes Survey','QILT','Graduate employment, salary and satisfaction measures published through QILT/ComparED.'),('qilt_gosl','Graduate Outcomes Survey - Longitudinal','QILT','Longitudinal graduate outcomes measures.'),('qilt_ess','Employer Satisfaction Survey','QILT','Employer satisfaction measures; publication granularity must be honoured.') on conflict(code) do update set name=excluded.name,source_family=excluded.source_family,description=excluded.description,updated_at=now();
